def list_chapters(language, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-chapters"
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_count(status, error_code=None, params=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

        usage = _load("usage_counters.json")
        if not isinstance(usage, dict): usage = {}
        usage.setdefault("global", {"total_requests": 0, "by_endpoint": {}, "by_day": {}})
        usage["global"]["total_requests"] = int(usage["global"].get("total_requests", 0)) + 1
        usage["global"].setdefault("by_endpoint", {})
        usage["global"]["by_endpoint"][endpoint] = int(usage["global"]["by_endpoint"].get(endpoint, 0)) + 1
        day = ts[:10]
        usage["global"].setdefault("by_day", {})
        usage["global"]["by_day"][day] = int(usage["global"]["by_day"].get(day, 0)) + 1
        _save("usage_counters.json", usage)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        recent = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            tss = r.get("timestamp")
            if not isinstance(tss, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(tss.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff:
                    recent += 1
                else:
                    break
            except Exception:
                continue
        if recent >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    params = {"language": language}

    rl = _ratelimit_check()
    if rl:
        _log_and_count("error", "RATE_LIMIT", params=params)
        return rl

    if not isinstance(language, str) or not (2 <= len(language) <= 10) or not re.fullmatch(r"^[a-zA-Z-]+$", language):
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return _err("VALIDATION_ERROR", "Invalid language", field="language")

    languages = _load("languages.json")
    if not isinstance(languages, list): languages = []
    lang_codes_active = {r.get("code") for r in languages if isinstance(r, dict) and r.get("status") == "active" and isinstance(r.get("code"), str)}
    if language not in lang_codes_active:
        _log_and_count("error", "NOT_FOUND", params=params)
        return _err("NOT_FOUND", "Language not available", field="language")

    default_lang = "en" if "en" in lang_codes_active else (next(iter(lang_codes_active), None) or language)

    chapters = _load("chapters.json")
    if not isinstance(chapters, list): chapters = []

    def _pick_localized(loc_arr, want, fallback):
        if not isinstance(loc_arr, list):
            return None
        chosen = None
        fb = None
        for e in loc_arr:
            if not isinstance(e, dict):
                continue
            lc = e.get("language_code")
            if lc == want:
                chosen = e
                break
            if lc == fallback:
                fb = e
        return chosen or fb

    out = []
    for ch in chapters:
        if not isinstance(ch, dict):
            continue
        if ch.get("status") != "published":
            continue
        loc = _pick_localized(ch.get("localized"), language, default_lang)
        if not isinstance(loc, dict):
            # Business rule: fallback without failing; if none at all, skip (cannot localize)
            continue
        out.append({
            "id": ch.get("id"),
            "chapter_number": ch.get("chapter_number"),
            "revelation_place": ch.get("revelation_place"),
            "verses_count": ch.get("verses_count"),
            "bismillah_pre": ch.get("bismillah_pre"),
            "name_arabic": ch.get("name_arabic"),
            "name": loc.get("name"),
            "short_name": loc.get("short_name"),
            "transliterated_name": loc.get("transliterated_name"),
            "chapter_info_html": loc.get("chapter_info_html"),
            "language_code": loc.get("language_code"),
        })

    try:
        out.sort(key=lambda x: int(x.get("chapter_number") or 0))
    except Exception:
        pass

    _log_and_count("ok", params=params)
    return {"chapters": out, "meta": {"language": language, "fallback_language": default_lang, "total": len(out)}}

def GET_chapter(language, id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "GET-chapter"
    now = datetime.datetime.utcnow()

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    ts = _iso(now)

    # --- observable service dynamics (logs + counters) ---
    def _new_req_id(logs_len):
        return f"qcom_req_{int(time.time() * 1000)}_{logs_len + 1}"

    def _append_log(status, error_code=None, params=None, resolved_language=None, chapter_number=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_req_id(len(logs)),
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status,
                "error_code": error_code,
                "params": params or {},
                "resolved_language": resolved_language,
                "chapter_number": chapter_number,
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

        usage = _load("usage_counters.json")
        if not isinstance(usage, dict):
            usage = {}
        usage.setdefault("global", {"total_requests": 0, "by_endpoint": {}, "by_day": {}})
        g = usage["global"]
        g["total_requests"] = int(g.get("total_requests", 0)) + 1
        g.setdefault("by_endpoint", {})
        g["by_endpoint"][endpoint] = int(g["by_endpoint"].get(endpoint, 0)) + 1
        day = ts[:10]
        g.setdefault("by_day", {})
        g["by_day"][day] = int(g["by_day"].get(day, 0)) + 1
        _save("usage_counters.json", usage)

    def _rate_limit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        window_seconds = cfg.get("window_seconds", None)
        max_requests = cfg.get("max_requests_per_window", None)
        try:
            if window_seconds is None or max_requests is None:
                return None
            window_seconds = int(window_seconds)
            max_requests = int(max_requests)
            if window_seconds <= 0 or max_requests <= 0:
                return None
        except (TypeError, ValueError):
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list) or not logs:
            return None

        now_epoch = int(time.time())
        cutoff = now_epoch - window_seconds

        def _parse_ts(s):
            try:
                # expects ISO like 2026-01-01T00:00:00Z
                return int(datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).timestamp())
            except Exception:
                return None

        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            tss = r.get("timestamp")
            if not isinstance(tss, str):
                continue
            ep = _parse_ts(tss)
            if ep is None:
                continue
            if ep >= cutoff:
                count += 1

        if count >= max_requests:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    params_for_log = {"language": language, "id": id}

    # Rate limit is enforced for every call; log is appended before returning.
    rl = _rate_limit_check()
    if rl:
        _append_log("error", error_code=rl["error"]["code"], params=params_for_log)
        return rl

    # --- validate language param ---
    if not isinstance(language, str):
        e = _err("VALIDATION_ERROR", "Invalid language; must be a string", field="language")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log)
        return e
    if not (2 <= len(language) <= 10) or re.match(r"^[a-zA-Z-]+$", language) is None:
        e = _err("VALIDATION_ERROR", "Invalid language", field="language")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log)
        return e

    languages = _load("languages.json")
    if not isinstance(languages, list):
        languages = []
    lang_codes = {r.get("code") for r in languages if isinstance(r, dict)}
    # Treat unknown language as validation error, per tool description
    if language not in lang_codes:
        e = _err("VALIDATION_ERROR", "Invalid language", field="language")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log)
        return e

    # --- validate/resolve chapter id ---
    # Real defect: caller passed "qcom_lang_ur" in id, which should not crash; we should be permissive:
    # - if id is digits -> interpret as chapter_number
    # - if id is int -> interpret as chapter_number
    # - otherwise, attempt to extract a chapter number from formats like qcom_ch_003 / qcom_chapter_3 / etc.
    # If we can't, respond with VALIDATION_ERROR (as vendor states).
    chap_num = None
    if id is None:
        # If omitted, default behavior isn't specified; treat as validation error.
        e = _err("VALIDATION_ERROR", "Invalid id; must be a positive integer", field="id")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log)
        return e

    if isinstance(id, bool):
        e = _err("VALIDATION_ERROR", "Invalid id; must be a positive integer", field="id")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log)
        return e

    if isinstance(id, int):
        chap_num = id
    elif isinstance(id, str):
        s = id.strip()
        if re.fullmatch(r"\d+", s or ""):
            try:
                chap_num = int(s)
            except ValueError:
                chap_num = None
        else:
            # try to extract trailing/embedded number
            m = re.search(r"(\d{1,3})", s)
            if m:
                try:
                    chap_num = int(m.group(1))
                except ValueError:
                    chap_num = None

    if chap_num is None or chap_num <= 0:
        e = _err("VALIDATION_ERROR", "Invalid id; must be a positive integer", field="id")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log)
        return e
    if chap_num < 1 or chap_num > 114:
        e = _err("VALIDATION_ERROR", "Invalid id; must be between 1 and 114", field="id")
        _append_log("error", error_code=e["error"]["code"], params=params_for_log, chapter_number=chap_num)
        return e

    chapters = _load("chapters.json")
    if not isinstance(chapters, list):
        chapters = []

    chapter = None
    for ch in chapters:
        if not isinstance(ch, dict):
            continue
        if ch.get("chapter_number") == chap_num:
            chapter = ch
            break

    # Tool description says NOT_FOUND if chapter id does not exist
    if not chapter:
        e = _err("NOT_FOUND", "Chapter not found", id=chap_num)
        _append_log("error", error_code=e["error"]["code"], params=params_for_log, chapter_number=chap_num)
        return e

    # Only published chapters are visible
    if chapter.get("status") != "published":
        e = _err("NOT_FOUND", "Chapter not found", id=chap_num)
        _append_log("error", error_code=e["error"]["code"], params=params_for_log, chapter_number=chap_num)
        return e

    localized = chapter.get("localized")
    if not isinstance(localized, list):
        localized = []

    def _pick_localization(lang_code):
        for loc in localized:
            if isinstance(loc, dict) and loc.get("language_code") == lang_code:
                return loc
        return None

    # Business rule: fallback to default language ('en') if missing, without failing.
    loc = _pick_localization(language)
    resolved_language = language
    if loc is None:
        loc = _pick_localization("en")
        resolved_language = "en" if loc is not None else language

    # If neither requested language nor fallback exists, return NOT_FOUND (as tool description mentions language not available)
    if loc is None:
        e = _err("NOT_FOUND", "Requested language is not available for this chapter", language=language, id=chap_num)
        _append_log("error", error_code=e["error"]["code"], params=params_for_log, resolved_language=resolved_language, chapter_number=chap_num)
        return e

    # Compose response: include localized fields merged with base chapter attributes.
    resp = {
        "chapter": {
            "id": chapter.get("id"),
            "chapter_number": chapter.get("chapter_number"),
            "revelation_place": chapter.get("revelation_place"),
            "verses_count": chapter.get("verses_count"),
            "bismillah_pre": chapter.get("bismillah_pre"),
            "name_arabic": chapter.get("name_arabic"),
            "status": chapter.get("status"),
            "name": loc.get("name"),
            "short_name": loc.get("short_name"),
            "transliterated_name": loc.get("transliterated_name"),
            "chapter_info_html": loc.get("chapter_info_html"),
            "language_code": resolved_language,
            "created_at": chapter.get("created_at"),
            "updated_at": chapter.get("updated_at"),
        }
    }

    _append_log("ok", params=params_for_log, resolved_language=resolved_language, chapter_number=chap_num)
    return resp

def info(language, chapter_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "info"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, params=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        usage = _load("usage_counters.json")
        if not isinstance(usage, dict): usage = {}
        usage.setdefault("global", {"total_requests": 0, "by_endpoint": {}, "by_day": {}})
        usage["global"]["total_requests"] = int(usage["global"].get("total_requests", 0)) + 1
        usage["global"].setdefault("by_endpoint", {})
        usage["global"]["by_endpoint"][endpoint] = int(usage["global"]["by_endpoint"].get(endpoint, 0)) + 1
        day = now[:10]
        usage["global"].setdefault("by_day", {})
        usage["global"]["by_day"][day] = int(usage["global"]["by_day"].get(day, 0)) + 1
        _save("usage_counters.json", usage)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.timestamp() < cutoff:
                break
            c += 1
            if c >= max_req:
                return _err("RATE_LIMIT", "Too many requests")
        return None

    if not isinstance(language, str) or len(language) < 2 or len(language) > 10 or re.fullmatch(r"^[a-zA-Z-]+$", language or "") is None:
        rl = _ratelimit_check()
        if rl:
            _log("error", {"language": language, "chapter_id": chapter_id}, "RATE_LIMIT")
            return rl
        _log("error", {"language": language, "chapter_id": chapter_id}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language is invalid", field="language")

    # Accept numeric chapter_id OR chapter primary key like qcom_ch_001
    chap_num = None
    if chapter_id is None:
        rl = _ratelimit_check()
        if rl:
            _log("error", {"language": language, "chapter_id": chapter_id}, "RATE_LIMIT")
            return rl
        _log("error", {"language": language, "chapter_id": chapter_id}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chapter_id is required", field="chapter_id")
    if isinstance(chapter_id, int):
        chap_num = chapter_id
    elif isinstance(chapter_id, str):
        s = chapter_id.strip()
        if re.fullmatch(r"^\d+$", s or ""):
            chap_num = int(s)
        else:
            m = re.fullmatch(r"^qcom_ch_(\d{3})$", s)
            if m:
                chap_num = int(m.group(1))
            else:
                rl = _ratelimit_check()
                if rl:
                    _log("error", {"language": language, "chapter_id": chapter_id}, "RATE_LIMIT")
                    return rl
                _log("error", {"language": language, "chapter_id": chapter_id}, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "chapter_id must be a positive integer", field="chapter_id")
    else:
        rl = _ratelimit_check()
        if rl:
            _log("error", {"language": language, "chapter_id": chapter_id}, "RATE_LIMIT")
            return rl
        _log("error", {"language": language, "chapter_id": chapter_id}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chapter_id must be a positive integer", field="chapter_id")

    if chap_num < 1 or chap_num > 114:
        rl = _ratelimit_check()
        if rl:
            _log("error", {"language": language, "chapter_id": chapter_id}, "RATE_LIMIT")
            return rl
        _log("error", {"language": language, "chapter_id": chapter_id}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chapter_id must be between 1 and 114", field="chapter_id")

    rl = _ratelimit_check()
    if rl:
        _log("error", {"language": language, "chapter_id": chapter_id}, "RATE_LIMIT")
        return rl

    languages = _load("languages.json")
    if not isinstance(languages, list):
        languages = []
    lang_exists = any(isinstance(r, dict) and r.get("code") == language for r in languages)
    if not lang_exists:
        _log("error", {"language": language, "chapter_id": chapter_id}, "NOT_FOUND")
        return _err("NOT_FOUND", "Requested language is not available", field="language")

    default_lang = "en"
    if not any(isinstance(r, dict) and r.get("code") == default_lang and r.get("status") == "active" for r in languages):
        for r in languages:
            if isinstance(r, dict) and r.get("status") == "active" and isinstance(r.get("code"), str):
                default_lang = r["code"]
                break

    chapters = _load("chapters.json")
    if not isinstance(chapters, list):
        chapters = []
    chapter = None
    for ch in chapters:
        if isinstance(ch, dict) and ch.get("chapter_number") == chap_num:
            chapter = ch
            break
    if not chapter or chapter.get("status") != "published":
        _log("error", {"language": language, "chapter_id": chapter_id}, "NOT_FOUND")
        return _err("NOT_FOUND", "Chapter not found", field="chapter_id")

    def _pick_localized(ch, lang_code):
        locs = ch.get("localized")
        if not isinstance(locs, list):
            return None
        for e in locs:
            if isinstance(e, dict) and e.get("language_code") == lang_code:
                return e
        return None

    loc = _pick_localized(chapter, language) or _pick_localized(chapter, default_lang)
    if not isinstance(loc, dict) or not isinstance(loc.get("chapter_info_html"), str) or loc.get("chapter_info_html") == "":
        _log("error", {"language": language, "chapter_id": chapter_id}, "NOT_FOUND")
        return _err("NOT_FOUND", "No chapter info exists for the requested language", field="language")

    _log("ok", {"language": language, "chapter_id": chapter_id})
    return {"chapter_id": chap_num, "language": loc.get("language_code"), "chapter_info_html": loc.get("chapter_info_html")}

def verses_by_chapter_number(chapter_number, language=None, words=None, translations=None, audio=None, tafsirs=None, word_fields=None, translation_fields=None, fields=None, page=None, per_page=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "verses-by_chapter_number"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, params=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.timestamp() < cutoff:
                break
            c += 1
            if c >= max_req:
                return _err("RATE_LIMIT", "Too many requests")
        return None

    def _parse_pos_int(name, v, min_v, max_v):
        if v is None:
            return None, _err("VALIDATION_ERROR", f"{name} is required", field=name)
        if isinstance(v, int):
            iv = v
        elif isinstance(v, str) and re.fullmatch(r"^\d+$", v.strip() or ""):
            iv = int(v.strip())
        else:
            return None, _err("VALIDATION_ERROR", f"{name} must be a positive integer", field=name)
        if iv < min_v or iv > max_v:
            return None, _err("VALIDATION_ERROR", f"{name} must be between {min_v} and {max_v}", field=name)
        return iv, None

    def _parse_page(v):
        if v is None or v == "":
            return 1, None
        if isinstance(v, int):
            iv = v
        elif isinstance(v, str) and re.fullmatch(r"^\d+$", v.strip() or ""):
            iv = int(v.strip())
        else:
            return None, _err("VALIDATION_ERROR", "page must be a positive integer", field="page")
        if iv < 1:
            return None, _err("VALIDATION_ERROR", "page must be >= 1", field="page")
        return iv, None

    def _parse_per_page(v):
        if v is None or v == "":
            return 10, None
        if isinstance(v, int):
            iv = v
        elif isinstance(v, str) and re.fullmatch(r"^\d+$", v.strip() or ""):
            iv = int(v.strip())
        else:
            return None, _err("VALIDATION_ERROR", "per_page must be a positive integer", field="per_page")
        if iv < 1:
            return None, _err("VALIDATION_ERROR", "per_page must be >= 1", field="per_page")
        if iv > 50:
            iv = 50
        return iv, None

    def _truthy(v):
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if not isinstance(v, str):
            return False
        return v.strip().lower() not in ("", "0", "false", "no", "off", "null", "none")

    def _parse_csv_ints_allow_empty(s, field_name):
        if s is None or s == "":
            return [], None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a comma-separated string of numeric ids", field=field_name)
        parts = [p.strip() for p in s.split(",") if p.strip() != ""]
        out = []
        for p in parts:
            if re.fullmatch(r"^\d+$", p) is None:
                return None, _err("VALIDATION_ERROR", f"{field_name} contains a non-numeric id: {p}", field=field_name)
            out.append(int(p))
        return out, None

    def _parse_csv_fields(s):
        if s is None or s == "":
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "fields must be a comma-separated string", field="fields")
        return [p.strip() for p in s.split(",") if p.strip() != ""], None

    def _validate_language_pref(code):
        if code is None:
            return None
        if not isinstance(code, str) or len(code) < 2 or len(code) > 10 or re.fullmatch(r"^[a-zA-Z-]+$", code) is None:
            return _err("VALIDATION_ERROR", "language is invalid", field="language")
        return None

    params = {"chapter_number": chapter_number, "language": language, "words": words, "translations": translations, "audio": audio, "tafsirs": tafsirs, "page": page, "per_page": per_page}
    rl = _ratelimit_check()
    if rl:
        _log("error", params, "RATE_LIMIT")
        return rl

    err = _validate_language_pref(language)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    chap_num, err = _parse_pos_int("chapter_number", chapter_number, 1, 114)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    pg, err = _parse_page(page)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err
    pp, err = _parse_per_page(per_page)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    trans_ids, err = _parse_csv_ints_allow_empty(translations, "translations")
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err
    tafsir_ids, err = _parse_csv_ints_allow_empty(tafsirs, "tafsirs")
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    audio_id = None
    if audio is not None and audio != "":
        if isinstance(audio, int):
            audio_id = audio
        elif isinstance(audio, str) and re.fullmatch(r"^\d+$", audio.strip() or ""):
            audio_id = int(audio.strip())
        else:
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "audio must be a numeric id", field="audio")

    word_fields_list = None
    if word_fields is not None and word_fields != "":
        if not isinstance(word_fields, str):
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "word_fields must be a comma-separated string", field="word_fields")
        word_fields_list = [p.strip() for p in word_fields.split(",") if p.strip() != ""]

    translation_fields_list = None
    if translation_fields is not None and translation_fields != "":
        if not isinstance(translation_fields, str):
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "translation_fields must be a comma-separated string", field="translation_fields")
        translation_fields_list = [p.strip() for p in translation_fields.split(",") if p.strip() != ""]

    verse_fields_list, err = _parse_csv_fields(fields)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    chapters = _load("chapters.json")
    if not isinstance(chapters, list): chapters = []
    ch_exists = any(isinstance(ch, dict) and ch.get("chapter_number") == chap_num for ch in chapters)
    if not ch_exists:
        _log("error", params, "NOT_FOUND")
        return _err("NOT_FOUND", "Chapter not found", field="chapter_number")

    verses = _load("verses.json")
    if not isinstance(verses, list): verses = []
    base = [v for v in verses if isinstance(v, dict) and v.get("status") == "published" and v.get("chapter_number") == chap_num]
    base.sort(key=lambda v: (v.get("verse_number") if isinstance(v.get("verse_number"), int) else 10**9))

    total = len(base)
    start = (pg - 1) * pp
    end = start + pp
    page_rows = base[start:end]
    has_more = end < total

    resources = _load("resources.json")
    if not isinstance(resources, list): resources = []

    def _find_resources(rtype, vendor_ids):
        found = []
        missing = []
        for vid in vendor_ids:
            r = None
            for row in resources:
                if isinstance(row, dict) and row.get("resource_type") == rtype and row.get("vendor_numeric_id") == vid:
                    r = row
                    break
            if not r or r.get("status") != "active":
                missing.append(vid)
            else:
                found.append(r)
        return found, missing

    trans_resources, missing_trans = _find_resources("translation", trans_ids)
    if missing_trans:
        _log("error", params, "NOT_FOUND")
        return _err("NOT_FOUND", "Requested translation not found or disabled", missing_ids=missing_trans, field="translations")
    tafsir_resources, missing_taf = _find_resources("tafsir", tafsir_ids)
    if missing_taf:
        _log("error", params, "NOT_FOUND")
        return _err("NOT_FOUND", "Requested tafsir not found or disabled", missing_ids=missing_taf, field="tafsirs")

    audio_resource = None
    if audio_id is not None:
        for row in resources:
            if isinstance(row, dict) and row.get("resource_type") == "reciter" and row.get("vendor_numeric_id") == audio_id and row.get("status") == "active":
                audio_resource = row
                break
        if not audio_resource:
            _log("error", params, "NOT_FOUND")
            return _err("NOT_FOUND", "Requested reciter not found or disabled", field="audio")

    def _project_word(w):
        if not isinstance(w, dict):
            return None
        if not word_fields_list:
            return w
        return {k: w[k] for k in word_fields_list if k in w}

    def _build_trans_item(res_row, verse_id):
        items = res_row.get("content_items")
        if not isinstance(items, list):
            return None
        payload = None
        for it in items:
            if isinstance(it, dict) and it.get("verse_id") == verse_id:
                payload = it
                break
        if payload is None:
            return None
        out = {}
        if translation_fields_list is None or len(translation_fields_list) == 0:
            out["text"] = payload.get("text")
            out["resource_name"] = res_row.get("name")
            out["language_code"] = res_row.get("language_code")
            out["translation_id"] = res_row.get("vendor_numeric_id")
        else:
            for f in translation_fields_list:
                if f == "text" and "text" in payload:
                    out["text"] = payload.get("text")
                elif f in ("resource_name", "name"):
                    out["resource_name"] = res_row.get("name")
                elif f == "language_code":
                    out["language_code"] = res_row.get("language_code")
                elif f in ("translation_id", "id"):
                    out["translation_id"] = res_row.get("vendor_numeric_id")
        return out if out else None

    def _build_tafsir_item(res_row, verse_id, tafsir_fields_list):
        items = res_row.get("content_items")
        if not isinstance(items, list):
            return None
        payload = None
        for it in items:
            if isinstance(it, dict) and it.get("verse_id") == verse_id:
                payload = it
                break
        if payload is None:
            return None
        out = {}
        if tafsir_fields_list is None or len(tafsir_fields_list) == 0:
            out = {"text": payload.get("text"), "tafsir_id": res_row.get("vendor_numeric_id"), "resource_name": res_row.get("name"), "language_code": res_row.get("language_code")}
        else:
            for f in tafsir_fields_list:
                if f == "text":
                    out["text"] = payload.get("text")
                elif f in ("tafsir_id", "id"):
                    out["tafsir_id"] = res_row.get("vendor_numeric_id")
                elif f in ("resource_name", "name"):
                    out["resource_name"] = res_row.get("name")
                elif f == "language_code":
                    out["language_code"] = res_row.get("language_code")
        return out if out else None

    def _build_audio_item(res_row, verse_id):
        items = res_row.get("content_items")
        if not isinstance(items, list):
            return None
        payload = None
        for it in items:
            if isinstance(it, dict) and it.get("verse_id") == verse_id:
                payload = it
                break
        if payload is None:
            return None
        return {"audio_url": payload.get("audio_url"), "duration_ms": payload.get("duration_ms"), "reciter_id": res_row.get("vendor_numeric_id"), "resource_name": res_row.get("name")}

    tafsir_fields_list = None
    if _truthy(tafsirs) and isinstance(_extra.get("fields"), str):
        tafsir_fields_list = [p.strip() for p in _extra.get("fields").split(",") if p.strip() != ""]

    results = []
    for v in page_rows:
        row = v if (verse_fields_list is None) else {k: v.get(k) for k in verse_fields_list if k in v}
        if _truthy(words):
            wj = v.get("words_json")
            if isinstance(wj, dict) and isinstance(wj.get("words"), list):
                row["words"] = [pw for pw in (_project_word(w) for w in wj.get("words")) if pw is not None]
            else:
                row["words"] = wj
        if trans_resources:
            verse_id = v.get("id")
            row["translations"] = [ti for ti in (_build_trans_item(r, verse_id) for r in trans_resources) if ti is not None]
        if tafsir_resources:
            verse_id = v.get("id")
            row["tafsirs"] = [ti for ti in (_build_tafsir_item(r, verse_id, None) for r in tafsir_resources) if ti is not None]
        if audio_resource is not None:
            verse_id = v.get("id")
            ai = _build_audio_item(audio_resource, verse_id)
            if ai is not None:
                row["audio"] = ai
        results.append(row)

    _log("ok", params)
    return {"verses": results, "meta": {"page": pg, "per_page": pp, "total": total, "has_more": has_more}}

def verses_by_page_number(page_number, language=None, words=None, translations=None, audio=None, tafsirs=None, word_fields=None, translation_fields=None, fields=None, page=None, per_page=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "verses-by_page_number"
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_count(status, error_code=None, params=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)
        usage = _load("usage_counters.json")
        if not isinstance(usage, dict): usage = {}
        usage.setdefault("global", {"total_requests": 0, "by_endpoint": {}, "by_day": {}})
        usage["global"]["total_requests"] = int(usage["global"].get("total_requests", 0)) + 1
        usage["global"].setdefault("by_endpoint", {})
        usage["global"]["by_endpoint"][endpoint] = int(usage["global"]["by_endpoint"].get(endpoint, 0)) + 1
        day = ts[:10]
        usage["global"].setdefault("by_day", {})
        usage["global"]["by_day"][day] = int(usage["global"]["by_day"].get(day, 0)) + 1
        _save("usage_counters.json", usage)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        recent = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            tss = r.get("timestamp")
            if not isinstance(tss, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(tss.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff:
                    recent += 1
                else:
                    break
            except Exception:
                continue
        if recent >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _parse_pos_int(name, v, min_v, max_v, required=True, default=None):
        if v is None or (isinstance(v, str) and v.strip() == ""):
            if required:
                return None, _err("VALIDATION_ERROR", f"{name} is required", field=name)
            return default, None
        if isinstance(v, int):
            iv = v
        elif isinstance(v, str):
            s = v.strip()
            if not re.fullmatch(r"^\d+$", s):
                return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
            iv = int(s)
        else:
            return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
        if iv < min_v or iv > max_v:
            return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
        return iv, None

    def _truthy(v):
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if isinstance(v, str):
            s = v.strip().lower()
            return s not in ("", "0", "false", "no", "off", "null", "none")
        return False

    def _parse_csv_ints(name, v):
        if v is None or (isinstance(v, str) and v.strip() == ""):
            return [], None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
        parts = [p.strip() for p in v.split(",") if p.strip() != ""]
        out = []
        for p in parts:
            if not re.fullmatch(r"^\d+$", p):
                return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
            out.append(int(p))
        return out, None

    def _parse_csv_fields(v):
        if v is None or (isinstance(v, str) and v.strip() == ""):
            return None
        if not isinstance(v, str):
            return []
        return [p.strip() for p in v.split(",") if p.strip()]

    params = {
        "page_number": page_number, "language": language, "words": words, "translations": translations,
        "audio": audio, "tafsirs": tafsirs, "word_fields": word_fields, "translation_fields": translation_fields,
        "fields": fields, "page": page, "per_page": per_page
    }

    rl = _ratelimit_check()
    if rl:
        _log_and_count("error", "RATE_LIMIT", params=params)
        return rl

    pn, e = _parse_pos_int("page_number", page_number, 1, 604, required=True)
    if e:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return e

    page_i, e = _parse_pos_int("page", page, 1, 10**9, required=False, default=1)
    if e:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return e

    per_page_i, e = _parse_pos_int("per_page", per_page, 1, 50, required=False, default=10)
    if e:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return e

    include_words = _truthy(words)
    requested_word_fields = _parse_csv_fields(word_fields)

    tr_ids, e = _parse_csv_ints("translations", translations)
    if e:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return e
    taf_ids, e = _parse_csv_ints("tafsirs", tafsirs)
    if e:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return e

    audio_vendor = None
    if audio is not None and not (isinstance(audio, str) and audio.strip() == ""):
        if isinstance(audio, str) and re.fullmatch(r"^\d+$", audio.strip()):
            audio_vendor = int(audio.strip())
        else:
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return _err("VALIDATION_ERROR", "Invalid audio", field="audio")

    verses = _load("verses.json")
    if not isinstance(verses, list): verses = []
    matching = [v for v in verses if isinstance(v, dict) and v.get("status") == "published" and v.get("page_number") == pn]
    matching.sort(key=lambda r: (int(r.get("chapter_number") or 0), int(r.get("verse_number") or 0)))

    total = len(matching)
    start = (page_i - 1) * per_page_i
    end = start + per_page_i
    page_rows = matching[start:end]
    has_more = end < total

    resources = _load("resources.json")
    if not isinstance(resources, list): resources = []

    # Resolve translation/tafsir/reciter resources (must be active)
    tr_res = []
    if tr_ids:
        for tid in tr_ids:
            found = next((r for r in resources if isinstance(r, dict) and r.get("resource_type") == "translation" and r.get("status") == "active" and r.get("vendor_numeric_id") == tid), None)
            if not found:
                _log_and_count("error", "NOT_FOUND", params=params)
                return _err("NOT_FOUND", "Translation not found", field="translations", translation_id=tid)
            tr_res.append(found)

    taf_res = []
    if taf_ids:
        for tid in taf_ids:
            found = next((r for r in resources if isinstance(r, dict) and r.get("resource_type") == "tafsir" and r.get("status") == "active" and r.get("vendor_numeric_id") == tid), None)
            if not found:
                _log_and_count("error", "NOT_FOUND", params=params)
                return _err("NOT_FOUND", "Tafsir not found", field="tafsirs", tafsir_id=tid)
            taf_res.append(found)

    reciter_res = None
    if audio_vendor is not None:
        reciter_res = next((r for r in resources if isinstance(r, dict) and r.get("resource_type") == "reciter" and r.get("status") == "active" and r.get("vendor_numeric_id") == audio_vendor), None)
        if not reciter_res:
            _log_and_count("error", "NOT_FOUND", params=params)
            return _err("NOT_FOUND", "Reciter not found", field="audio", audio=audio_vendor)

    translation_field_list = _parse_csv_fields(translation_fields)

    ayah_field_list = _parse_csv_fields(fields)
    allowed_ayah_fields = {
        "id","chapter_id","chapter_number","verse_number","verse_key","text_uthmani",
        "page_number","juz_number","hizb_number","rub_el_hizb_number","words"
    }

    def _proj_ayah(vrow):
        base = {
            "id": vrow.get("id"),
            "chapter_id": vrow.get("chapter_id"),
            "chapter_number": vrow.get("chapter_number"),
            "verse_number": vrow.get("verse_number"),
            "verse_key": vrow.get("verse_key"),
            "text_uthmani": vrow.get("text_uthmani"),
            "page_number": vrow.get("page_number"),
            "juz_number": vrow.get("juz_number"),
            "hizb_number": vrow.get("hizb_number"),
            "rub_el_hizb_number": vrow.get("rub_el_hizb_number"),
        }
        if ayah_field_list is None:
            return base
        out = {}
        for k in ayah_field_list:
            if k in allowed_ayah_fields:
                if k == "words":
                    continue
                out[k] = base.get(k)
        # always include id and verse_key for stability
        out.setdefault("id", base.get("id"))
        out.setdefault("verse_key", base.get("verse_key"))
        return out

    def _filter_word_obj(wobj):
        if not isinstance(wobj, dict):
            return wobj
        if not requested_word_fields:
            return wobj
        return {k: wobj.get(k) for k in requested_word_fields if k in wobj}

    def _attach_enrichments(vout, vrow):
        if include_words:
            wj = vrow.get("words_json")
            if isinstance(wj, dict) and "words" in wj and isinstance(wj.get("words"), list):
                vout["words"] = [_filter_word_obj(w) for w in wj.get("words")]
            else:
                vout["words"] = wj

        if tr_res:
            vout["translations"] = []
            for r in tr_res:
                items = r.get("content_items")
                txt = None
                if isinstance(items, list):
                    for it in items:
                        if isinstance(it, dict) and it.get("verse_id") == vrow.get("id"):
                            txt = it.get("text")
                            break
                obj = {
                    "translation_id": r.get("vendor_numeric_id"),
                    "resource_id": r.get("id"),
                    "resource_name": r.get("name"),
                    "language_code": r.get("language_code"),
                    "text": txt,
                }
                if translation_field_list:
                    obj = {k: obj.get(k) for k in translation_field_list if k in obj}
                    obj.setdefault("translation_id", r.get("vendor_numeric_id"))
                vout["translations"].append(obj)

