        _log("error", params, "RATE_LIMIT")
        return rl

    jn, err = _parse_pos_int("juz_number", juz_number, 1, 30)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err
    pg, err = _parse_page(page)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err
    pp, err = _parse_per_page(per_page)
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    trans_ids, err = _parse_csv_ints_allow_empty(translations, "translations")
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err
    tafsir_ids, err = _parse_csv_ints_allow_empty(tafsirs, "tafsirs")
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

