        "page_number","juz_number","hizb_number","rub_el_hizb_number","words"
    }

    base = {
        "id": vrow.get("id"),
        "chapter_id": vrow.get("chapter_id"),
        "chapter_number": vrow.get("chapter_number"),
        "verse_number": vrow.get("verse_number"),
        "verse_key": vrow.get("verse_key"),
        "text_uthmani": vrow.get("text_uthmani"),
        "page_number": vrow.get("page_number"),
        "juz_number": vrow.get("juz_number"),
        "hizb_number": vrow.get("hizb_number"),
        "rub_el_hizb_number": vrow.get("rub_el_hizb_number"),
    }

    if ayah_field_list is None:
        out = dict(base)
    else:
        out = {}
        for k in ayah_field_list:
            if k in allowed_ayah_fields and k != "words":
                out[k] = base.get(k)
        out.setdefault("id", base.get("id"))
        out.setdefault("verse_key", base.get("verse_key"))

    if include_words:
        wj = vrow.get("words_json")
        def _filter_word_obj(wobj):
            if not isinstance(wobj, dict):
                return wobj
            if not requested_word_fields:
                return wobj
            return {k: wobj.get(k) for k in requested_word_fields if k in wobj}
        if isinstance(wj, dict) and "words" in wj and isinstance(wj.get("words"), list):
            out["words"] = [_filter_word_obj(w) for w in wj.get("words")]
        else:
            out["words"] = wj

    if tr_res:
        out["translations"] = []
        for r in tr_res:
            items = r.get("content_items")
            txt = None
            if isinstance(items, list):
                for it in items:
                    if isinstance(it, dict) and it.get("verse_id") == vrow.get("id"):
                        txt = it.get("text")
                        break
            obj = {
                "translation_id": r.get("vendor_numeric_id"),
                "resource_id": r.get("id"),
                "resource_name": r.get("name"),
                "language_code": r.get("language_code"),
                "text": txt,
            }
            if translation_field_list:
                obj = {k: obj.get(k) for k in translation_field_list if k in obj}
                obj.setdefault("translation_id", r.get("vendor_numeric_id"))
            out["translations"].append(obj)

    if taf_res:
        out["tafsirs"] = []
        for r in taf_res:
            items = r.get("content_items")
            txt = None
            if isinstance(items, list):
                for it in items:
                    if isinstance(it, dict) and it.get("verse_id") == vrow.get("id"):
                        txt = it.get("text")
                        break
            out["tafsirs"].append({
                "tafsir_id": r.get("vendor_numeric_id"),
                "resource_id": r.get("id"),
                "resource_name": r.get("name"),
                "language_code": r.get("language_code"),
                "text": txt,
            })

    if reciter_res is not None:
        items = reciter_res.get("content_items")
        audio_url = None
        duration_ms = None
        if isinstance(items, list):
            for it in items:
                if isinstance(it, dict) and it.get("verse_id") == vrow.get("id"):
                    audio_url = it.get("audio_url")
                    duration_ms = it.get("duration_ms")
                    break
        out["audio"] = {
            "reciter_id": reciter_res.get("vendor_numeric_id"),
            "resource_id": reciter_res.get("id"),
            "audio_url": audio_url,
            "duration_ms": duration_ms,
        }

    _log_and_count("ok", params=params)
    return {"verse": out}

def random_verse(language=None, words=None, translations=None, audio=None, tafsirs=None, word_fields=None, translation_fields=None, fields=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "random_verse"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, params=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.timestamp() < cutoff:
                break
            c += 1
            if c >= max_req:
                return _err("RATE_LIMIT", "Too many requests")
        return None

    def _truthy(v):
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if not isinstance(v, str):
            return False
        return v.strip().lower() not in ("", "0", "false", "no", "off", "null", "none")

    def _parse_csv_ints_lenient(s, field_name):
        # Lenient for this tool: if string contains no numeric ids, treat as "not provided"
        if s is None or s == "":
            return [], None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a comma-separated string of numeric ids", field=field_name)
        parts = [p.strip() for p in s.split(",") if p.strip() != ""]
        out = []
        for p in parts:
            if re.fullmatch(r"^\d+$", p):
                out.append(int(p))
            else:
                # instead of failing (audit passed qcom_lang_en), ignore non-numeric tokens
                continue
        return out, None

    params = {"language": language, "words": words, "translations": translations, "audio": audio, "tafsirs": tafsirs, "word_fields": word_fields, "translation_fields": translation_fields, "fields": fields}
    rl = _ratelimit_check()
    if rl:
        _log("error", params, "RATE_LIMIT")
        return rl

    # Validate language if provided (preference only)
    if language is not None:
        if not isinstance(language, str) or len(language) < 2 or len(language) > 10 or re.fullmatch(r"^[a-zA-Z-]+$", language) is None:
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "language is invalid", field="language")

    trans_ids, err = _parse_csv_ints_lenient(translations, "translations")
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err
    tafsir_ids, err = _parse_csv_ints_lenient(tafsirs, "tafsirs")
    if err:
        _log("error", params, "VALIDATION_ERROR")
        return err

    audio_id = None
    if audio is not None and audio != "":
        if isinstance(audio, int):
            audio_id = audio
        elif isinstance(audio, str) and re.fullmatch(r"^\d+$", audio.strip() or ""):
            audio_id = int(audio.strip())
        else:
            # lenient: ignore if not numeric
            audio_id = None

    word_fields_list = None
    if word_fields is not None and word_fields != "":
        if isinstance(word_fields, str):
            word_fields_list = [p.strip() for p in word_fields.split(",") if p.strip() != ""]
        else:
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "word_fields must be a comma-separated string", field="word_fields")

    translation_fields_list = None
    if translation_fields is not None and translation_fields != "":
        if isinstance(translation_fields, str):
            translation_fields_list = [p.strip() for p in translation_fields.split(",") if p.strip() != ""]
        else:
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "translation_fields must be a comma-separated string", field="translation_fields")

    verse_fields_list = None
    if fields is not None and fields != "":
        if isinstance(fields, str):
            verse_fields_list = [p.strip() for p in fields.split(",") if p.strip() != ""]
        else:
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fields must be a comma-separated string", field="fields")

    verses = _load("verses.json")
    if not isinstance(verses, list): verses = []
    published = [v for v in verses if isinstance(v, dict) and v.get("status") == "published"]
    if not published:
        _log("error", params, "NOT_FOUND")
        return _err("NOT_FOUND", "No published verses available")
    v = random.choice(published)

    resources = _load("resources.json")
    if not isinstance(resources, list): resources = []

    def _find_resources(rtype, vendor_ids):
        found = []
        missing = []
        for vid in vendor_ids:
            r = None
            for row in resources:
                if isinstance(row, dict) and row.get("resource_type") == rtype and row.get("vendor_numeric_id") == vid:
                    r = row
                    break
            if not r or r.get("status") != "active":
                missing.append(vid)
            else:
                found.append(r)
        return found, missing

    trans_resources, missing_trans = _find_resources("translation", trans_ids)
    if missing_trans:
        _log("error", params, "NOT_FOUND")
        return _err("NOT_FOUND", "Requested translation not found or disabled", missing_ids=missing_trans, field="translations")
    tafsir_resources, missing_taf = _find_resources("tafsir", tafsir_ids)
    if missing_taf:
        _log("error", params, "NOT_FOUND")
        return _err("NOT_FOUND", "Requested tafsir not found or disabled", missing_ids=missing_taf, field="tafsirs")

    audio_resource = None
    if audio_id is not None:
        for row in resources:
            if isinstance(row, dict) and row.get("resource_type") == "reciter" and row.get("vendor_numeric_id") == audio_id and row.get("status") == "active":
                audio_resource = row
                break
        if not audio_resource:
            _log("error", params, "NOT_FOUND")
            return _err("NOT_FOUND", "Requested reciter not found or disabled", field="audio")

    def _project_word(w):
        if not isinstance(w, dict):
            return None
        if not word_fields_list:
            return w
        return {k: w[k] for k in word_fields_list if k in w}

    def _build_trans_item(res_row, verse_id):
        items = res_row.get("content_items")
        if not isinstance(items, list):
            return None
        payload = None
        for it in items:
            if isinstance(it, dict) and it.get("verse_id") == verse_id:
                payload = it
                break
        if payload is None:
            return None
        out = {}
        if translation_fields_list is None or len(translation_fields_list) == 0:
            out["text"] = payload.get("text")
            out["resource_name"] = res_row.get("name")
            out["language_code"] = res_row.get("language_code")
            out["translation_id"] = res_row.get("vendor_numeric_id")
        else:
            for f in translation_fields_list:
                if f == "text":
                    out["text"] = payload.get("text")
                elif f in ("resource_name", "name"):
                    out["resource_name"] = res_row.get("name")
                elif f == "language_code":
                    out["language_code"] = res_row.get("language_code")
                elif f in ("translation_id", "id"):
                    out["translation_id"] = res_row.get("vendor_numeric_id")
        return out if out else None

    def _build_tafsir_item(res_row, verse_id):
        items = res_row.get("content_items")
        if not isinstance(items, list):
            return None
        payload = None
        for it in items:
            if isinstance(it, dict) and it.get("verse_id") == verse_id:
                payload = it
                break
        if payload is None:
            return None
        return {"text": payload.get("text"), "tafsir_id": res_row.get("vendor_numeric_id"), "resource_name": res_row.get("name"), "language_code": res_row.get("language_code")}

    def _build_audio_item(res_row, verse_id):
        items = res_row.get("content_items")
        if not isinstance(items, list):
            return None
        payload = None
        for it in items:
            if isinstance(it, dict) and it.get("verse_id") == verse_id:
                payload = it
                break
        if payload is None:
            return None
        return {"audio_url": payload.get("audio_url"), "duration_ms": payload.get("duration_ms"), "reciter_id": res_row.get("vendor_numeric_id"), "resource_name": res_row.get("name")}

    out = v if verse_fields_list is None else {k: v.get(k) for k in verse_fields_list if k in v}
    if _truthy(words):
        wj = v.get("words_json")
        if isinstance(wj, dict) and isinstance(wj.get("words"), list):
            out["words"] = [pw for pw in (_project_word(w) for w in wj.get("words")) if pw is not None]
        else:
            out["words"] = wj
    if trans_resources:
        verse_id = v.get("id")
        out["translations"] = [ti for ti in (_build_trans_item(r, verse_id) for r in trans_resources) if ti is not None]
    if tafsir_resources:
        verse_id = v.get("id")
        out["tafsirs"] = [ti for ti in (_build_tafsir_item(r, verse_id) for r in tafsir_resources) if ti is not None]
    if audio_resource is not None:
        verse_id = v.get("id")
        ai = _build_audio_item(audio_resource, verse_id)
        if ai is not None:
            out["audio"] = ai

    _log("ok", params)
    return {"verse": out}

def juzs(language=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "juzs"

    def _ensure_request_log():
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list): reqs = []
        return reqs

    def _log(reqs, status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(reqs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": datetime.datetime.utcnow().isoformat() + "Z",
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    reqs = _ensure_request_log()
    try:
        if language is not None:
            if not isinstance(language, str):
                _log(reqs, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "language must be a string")
            if not (2 <= len(language) <= 10) or not re.fullmatch(r"[a-zA-Z-]+", language):
                _log(reqs, "error", "VALIDATION_ERROR")
                # Tool description says BAD_REQUEST; we map to VALIDATION_ERROR per allowed codes.
                return _err("VALIDATION_ERROR", "language must be 2-10 chars and match ^[a-zA-Z-]+$")

        verses = _load("verses.json")
        if not isinstance(verses, list): verses = []
        published = [v for v in verses if isinstance(v, dict) and v.get("status") == "published"]

        # Boundary per juz from published verses; if none, still return 30 with null boundaries.
        by_juz = {}
        for v in published:
            j = v.get("juz_number")
            vk = v.get("verse_key")
            if not isinstance(j, int) or not (1 <= j <= 30) or not isinstance(vk, str):
                continue
            by_juz.setdefault(j, []).append(vk)

        out = []
        for j in range(1, 31):
            vks = by_juz.get(j, [])
            if vks:
                # verse_key ordering: numeric chapter then verse
                def _vk_key(x):
                    try:
                        a, b = x.split(":")
                        return (int(a), int(b))
                    except Exception:
                        return (10**9, 10**9)
                vks_sorted = sorted(vks, key=_vk_key)
                first_vk = vks_sorted[0]
                last_vk = vks_sorted[-1]
            else:
                first_vk = None
                last_vk = None
            out.append({
                "juz_number": j,
                "first_verse_key": first_vk,
                "last_verse_key": last_vk,
                "language": language if language is not None else None
            })

        _log(reqs, "ok", None)
        return {"juzs": out}
    except Exception as ex:
        _log(reqs, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected server error", detail=str(ex))

def search(q, size=None, page=None, language=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search"

    def _ensure_request_log():
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list): reqs = []
        return reqs

    def _log(reqs, status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(reqs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": datetime.datetime.utcnow().isoformat() + "Z",
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _parse_pos_int(s, name, default=None):
        if s is None or s == "":
            return default, None
        if isinstance(s, int):
            v = s
        elif isinstance(s, str):
            if not re.fullmatch(r"\d+", s.strip()):
                return None, _err("VALIDATION_ERROR", f"{name} must be a positive integer")
            v = int(s.strip())
        else:
            return None, _err("VALIDATION_ERROR", f"{name} must be a positive integer")
        if v < 1:
            return None, _err("VALIDATION_ERROR", f"{name} must be >= 1")
        return v, None

    reqs = _ensure_request_log()
    try:
        if q is None or not isinstance(q, str) or q.strip() == "":
            _log(reqs, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "q is required")

        page_i, e = _parse_pos_int(page, "page", default=1)
        if e:
            _log(reqs, "error", "VALIDATION_ERROR"); return e
        size_i, e = _parse_pos_int(size, "size", default=10)
        if e:
            _log(reqs, "error", "VALIDATION_ERROR"); return e
        if size_i < 1 or size_i > 50:
            _log(reqs, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "size must be between 1 and 50")

        if language is not None:
            if not isinstance(language, str) or not (2 <= len(language) <= 10) or not re.fullmatch(r"[a-zA-Z-]+", language):
                _log(reqs, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "language must be 2-10 chars and match ^[a-zA-Z-]+$")

        verses = _load("verses.json")
        resources = _load("resources.json")
        search_queries = _load("search_queries.json")
        if not isinstance(verses, list): verses = []
        if not isinstance(resources, list): resources = []
        if not isinstance(search_queries, list): search_queries = []

        qnorm = q.strip().lower()

        # Build a simple inverted search across:
        # - verse_key exact/substring
        # - text_uthmani substring
        # - translation texts (active translations), boosted by requested language
        active_translations = [r for r in resources if isinstance(r, dict) and r.get("resource_type") == "translation" and r.get("status") == "active"]
        boost_translation_ids = set()
        if language:
            for r in active_translations:
                if r.get("language_code") == language:
                    boost_translation_ids.add(r.get("id"))
                locs = r.get("localizations") or []
                if isinstance(locs, list):
                    for loc in locs:
                        if isinstance(loc, dict) and loc.get("language_code") == language:
                            boost_translation_ids.add(r.get("id"))
                            break

        # Map verse_id -> list of translation texts (and whether boosted)
        tr_texts = {}
        for tr in active_translations:
            ci = tr.get("content_items") or []
            if not isinstance(ci, list):
                continue
            is_boost = tr.get("id") in boost_translation_ids
            for item in ci:
                if not isinstance(item, dict):
                    continue
                vid = item.get("verse_id")
                txt = item.get("text")
                if not isinstance(vid, str) or not isinstance(txt, str):
                    continue
                tr_texts.setdefault(vid, []).append((txt, is_boost))

        scored = []
        for v in verses:
            if not isinstance(v, dict) or v.get("status") != "published":
                continue
            score = 0
            vk = v.get("verse_key") or ""
            ar = v.get("text_uthmani") or ""
            if isinstance(vk, str) and qnorm in vk.lower():
                score += 5
            if isinstance(ar, str) and qnorm in ar.lower():
                score += 3
            # translation matches
            vid = v.get("id")
            for txt, is_boost in tr_texts.get(vid, []):
                if qnorm in txt.lower():
                    score += 2 + (2 if is_boost else 0)
            if score > 0:
                scored.append((score, v))

        # Sort by score desc, then by verse_key numeric
        def _vk_key(vkstr):
            try:
                a, b = vkstr.split(":")
                return (int(a), int(b))
            except Exception:
                return (10**9, 10**9)

        scored.sort(key=lambda sv: (-sv[0], _vk_key(sv[1].get("verse_key", "999:999"))))
        hits = [v for _, v in scored]
        total = len(hits)

        start = (page_i - 1) * size_i
        end = start + size_i
        page_items = hits[start:end]
        has_more = end < total

        result_verse_ids = [v.get("id") for v in page_items if isinstance(v.get("id"), str)]

        now = datetime.datetime.utcnow().isoformat() + "Z"
        sq_id = f"qcom_sq_{int(time.time()*1000)}_{len(search_queries)+1}"
        sq_row = {
            "id": sq_id,
            "query_text": q.strip(),
            "language_code": language if language else None,
            "page": page_i,
            "size": size_i,
            "result_verse_ids": result_verse_ids,
            "result_total": total,
            "engine_metadata_json": {"backend": "local_simple", "scored_hits": len(scored)},
            "status": "completed",
            "created_at": now,
