        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Request log + simple rate limiting (observable dynamics) ---
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Rolling window: 60s, max 120 calls
    window_s = 60
    max_calls = 120
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs[-2000:]:
        if isinstance(r, dict) and r.get("timestamp") and r["timestamp"] >= cutoff:
            recent += 1
    if recent >= max_calls:
        row = {
            "id": f"req_{len(logs)+1}",
            "endpoint": "translations",
            "params": {"language": language},
            "status": "RATE_LIMIT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Too many requests")

    # --- Validate inputs ---
    if language is not None and not isinstance(language, str):
        status = "VALIDATION_ERROR"
        row = {
            "id": f"req_{len(logs)+1}",
            "endpoint": "translations",
            "params": {"language": language},
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "language must be a string")

    languages = _load("languages.json")
    if not isinstance(languages, list):
        languages = []
    lang_row = None
    if language is not None:
        if not (2 <= len(language) <= 10) or re.fullmatch(r"[a-zA-Z-]+", language) is None:
            status = "VALIDATION_ERROR"
            row = {
                "id": f"req_{len(logs)+1}",
                "endpoint": "translations",
                "params": {"language": language},
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(row)
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Invalid language")
        for l in languages:
            if isinstance(l, dict) and l.get("code") == language and l.get("status") == "active":
                lang_row = l
                break
        if lang_row is None:
            status = "VALIDATION_ERROR"
            row = {
                "id": f"req_{len(logs)+1}",
                "endpoint": "translations",
                "params": {"language": language},
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(row)
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Invalid language")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    def _localized_name(res, pref_code):
        name = res.get("name")
        if pref_code is None:
            return name
        locs = res.get("localizations")
        if isinstance(locs, list):
            for loc in locs:
                if isinstance(loc, dict) and loc.get("language_code") == pref_code and isinstance(loc.get("name"), str):
                    return loc["name"]
        return name

    out = []
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "translation":
            continue
        if r.get("status") != "active":
            continue
        if r.get("vendor_numeric_id") is None:
            continue

        if language is not None:
            # include if primary language matches OR has localization for language
            ok = (r.get("language_code") == language)
            if not ok:
                locs = r.get("localizations")
                if isinstance(locs, list):
                    for loc in locs:
                        if isinstance(loc, dict) and loc.get("language_code") == language:
                            ok = True
                            break
            if not ok:
                continue

        out.append({
            "id": r.get("id"),
            "translation_id": r.get("vendor_numeric_id"),
            "name": _localized_name(r, language),
            "language_code": r.get("language_code"),
            "author_name": r.get("author_name"),
            "slug": r.get("slug"),
            "status": r.get("status"),
        })

    # Stable ordering: by language_code then id
    out.sort(key=lambda x: ((x.get("language_code") or ""), str(x.get("translation_id") or ""), str(x.get("id") or "")))

    row = {
        "id": f"req_{len(logs)+1}",
        "endpoint": "translations",
        "params": {"language": language},
        "status": "OK",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(row)
    _save("request_logs.json", logs)

    return {"translations": out, "meta": {"total": len(out)}}

