    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "translation-info"
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_count(status, error_code=None, params=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
