            "timestamp": ts,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)
        usage = _load("usage_counters.json")
        if not isinstance(usage, dict): usage = {}
        usage.setdefault("global", {"total_requests": 0, "by_endpoint": {}, "by_day": {}})
        usage["global"]["total_requests"] = int(usage["global"].get("total_requests", 0)) + 1
        usage["global"].setdefault("by_endpoint", {})
        usage["global"]["by_endpoint"][endpoint] = int(usage["global"]["by_endpoint"].get(endpoint, 0)) + 1
        day = ts[:10]
        usage["global"].setdefault("by_day", {})
        usage["global"]["by_day"][day] = int(usage["global"]["by_day"].get(day, 0)) + 1
        _save("usage_counters.json", usage)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        recent = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            tss = r.get("timestamp")
            if not isinstance(tss, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(tss.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff:
                    recent += 1
                else:
                    break
            except Exception:
                continue
        if recent >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    params = {"translation_id": translation_id}

    rl = _ratelimit_check()
    if rl:
        _log_and_count("error", "RATE_LIMIT", params=params)
        return rl

