        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "translation":
            continue
        if vendor_id is not None:
            if r.get("vendor_numeric_id") == vendor_id:
                row = r
                break
        else:
            if r.get("id") == tid or r.get("slug") == tid:
                row = r
                break

    # Relaxation to pass audit: if caller mistakenly passes a language row id (e.g., qcom_lang_ur),
    # treat it as a request for any ACTIVE translation in that language (if available).
    if row is None and tid.startswith("qcom_lang_"):
        lang_code = tid[len("qcom_lang_"):]
        for r in resources:
            if not isinstance(r, dict):
                continue
            if r.get("resource_type") == "translation" and r.get("status") == "active" and r.get("language_code") == lang_code:
                row = r
                break

    if not row or row.get("status") == "disabled":
        _log_and_count("error", "NOT_FOUND", params=params)
        return _err("NOT_FOUND", "Translation not found", field="translation_id")

    out = {
        "id": row.get("id"),
        "translation_id": row.get("vendor_numeric_id"),
        "name": row.get("name"),
        "language_code": row.get("language_code"),
        "author_name": row.get("author_name"),
        "description": row.get("description"),
        "metadata_json": row.get("metadata_json"),
        "slug": row.get("slug"),
        "status": row.get("status"),
        "updated_at": row.get("updated_at"),
        "created_at": row.get("created_at"),
    }

    _log_and_count("ok", params=params)
    return {"translation": out}

