        usage["global"]["total_requests"] = int(usage["global"].get("total_requests", 0)) + 1
        usage["global"].setdefault("by_endpoint", {})
        usage["global"]["by_endpoint"][endpoint] = int(usage["global"]["by_endpoint"].get(endpoint, 0)) + 1
        day = ts[:10]
        usage["global"].setdefault("by_day", {})
        usage["global"]["by_day"][day] = int(usage["global"]["by_day"].get(day, 0)) + 1
        _save("usage_counters.json", usage)

    def _ratelimit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        try:
            window_s = int(cfg.get("window_seconds", 60))
            max_req = cfg.get("max_requests_per_window", None)
            if max_req is None:
                return None
            max_req = int(max_req)
        except Exception:
            return None
        if window_s <= 0 or max_req <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - window_s
        recent = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            tss = r.get("timestamp")
            if not isinstance(tss, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(tss.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff:
                    recent += 1
                else:
                    break
            except Exception:
                continue
        if recent >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _parse_pos_int_optional(name, v, min_v, max_v):
        if v is None or (isinstance(v, str) and v.strip() == ""):
            return None, None
        if isinstance(v, int):
            iv = v
        elif isinstance(v, str) and re.fullmatch(r"^\d+$", v.strip()):
            iv = int(v.strip())
        else:
            return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
        if iv < min_v or iv > max_v:
            return None, _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
        return iv, None

    def _parse_field_list(v):
        if v is None or (isinstance(v, str) and v.strip() == ""):
            return None
        if not isinstance(v, str):
            return []
        return [p.strip() for p in v.split(",") if p.strip()]

    params = {
        "tafsir_id": tafsir_id, "fields": fields, "chapter_number": chapter_number, "juz_number": juz_number,
        "page_number": page_number, "hizb_number": hizb_number, "rub_el_hizb_number": rub_el_hizb_number,
        "verse_key": verse_key
    }

    rl = _ratelimit_check()
    if rl:
        _log_and_count("error", "RATE_LIMIT", params=params)
        return rl

    if tafsir_id is None or not isinstance(tafsir_id, str) or tafsir_id.strip() == "":
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return _err("VALIDATION_ERROR", "tafsir_id is required", field="tafsir_id")
    tid = tafsir_id.strip()

    # Selector resolution: prefer the first valid selector in a stable priority order.
    # This relaxes the "exactly one selector" rule to accept ambiguous calls seen in audit,
    # while still enforcing validity of the chosen selector.
    selector_order = ["verse_key", "chapter_number", "juz_number", "page_number", "hizb_number", "rub_el_hizb_number"]
    selectors = {
        "chapter_number": chapter_number,
        "juz_number": juz_number,
        "page_number": page_number,
        "hizb_number": hizb_number,
        "rub_el_hizb_number": rub_el_hizb_number,
        "verse_key": verse_key,
    }
    provided = [k for k, v in selectors.items() if v is not None and not (isinstance(v, str) and v.strip() == "")]
    if not provided:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return _err("VALIDATION_ERROR", "A scope selector must be provided", field="selector")
    chosen = next((k for k in selector_order if k in provided), provided[0])

    # Parse chosen selector
    chosen_val = selectors.get(chosen)
    chosen_verses = None

    verses = _load("verses.json")
    if not isinstance(verses, list): verses = []
    verses_pub = [v for v in verses if isinstance(v, dict) and v.get("status") == "published"]

    if chosen == "verse_key":
        if not isinstance(chosen_val, str) or not re.fullmatch(r"^\d{1,3}:\d{1,3}$", chosen_val.strip()):
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return _err("VALIDATION_ERROR", "Invalid verse_key; must be in 'chapter:verse' format", field="verse_key")
        vk = chosen_val.strip()
        chosen_verses = [v for v in verses_pub if v.get("verse_key") == vk]
    elif chosen == "chapter_number":
        cn, e = _parse_pos_int_optional("chapter_number", chosen_val, 1, 114)
        if e:
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return e
        chosen_verses = [v for v in verses_pub if v.get("chapter_number") == cn]
    elif chosen == "juz_number":
        jn, e = _parse_pos_int_optional("juz_number", chosen_val, 1, 30)
        if e:
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return e
        chosen_verses = [v for v in verses_pub if v.get("juz_number") == jn]
    elif chosen == "page_number":
        pn, e = _parse_pos_int_optional("page_number", chosen_val, 1, 604)
        if e:
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return e
        chosen_verses = [v for v in verses_pub if v.get("page_number") == pn]
    elif chosen == "hizb_number":
        hn, e = _parse_pos_int_optional("hizb_number", chosen_val, 1, 60)
        if e:
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return e
        chosen_verses = [v for v in verses_pub if v.get("hizb_number") == hn]
    elif chosen == "rub_el_hizb_number":
        rn, e = _parse_pos_int_optional("rub_el_hizb_number", chosen_val, 1, 240)
        if e:
            _log_and_count("error", "VALIDATION_ERROR", params=params)
            return e
        chosen_verses = [v for v in verses_pub if v.get("rub_el_hizb_number") == rn]
    else:
        _log_and_count("error", "VALIDATION_ERROR", params=params)
        return _err("VALIDATION_ERROR", "Invalid selector", field="selector")

    # Resolve tafsir resource: accept numeric vendor id or resource id/slug; also accept qcom_lang_* as language preference.
    resources = _load("resources.json")
    if not isinstance(resources, list): resources = []

    taf_row = None
    vendor_id = int(tid) if re.fullmatch(r"^\d+$", tid) else None
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("resource_type") != "tafsir":
            continue
        if r.get("status") != "active":
            continue
        if vendor_id is not None:
            if r.get("vendor_numeric_id") == vendor_id:
                taf_row = r
                break
        else:
            if r.get("id") == tid or r.get("slug") == tid:
                taf_row = r
                break

    if taf_row is None and tid.startswith("qcom_lang_"):
        lang_code = tid[len("qcom_lang_"):]
        for r in resources:
            if not isinstance(r, dict):
                continue
            if r.get("resource_type") == "tafsir" and r.get("status") == "active" and r.get("language_code") == lang_code:
                taf_row = r
                break

    if taf_row is None:
        _log_and_count("error", "NOT_FOUND", params=params)
        return _err("NOT_FOUND", "Tafsir not found", field="tafsir_id")

    verse_ids = [v.get("id") for v in chosen_verses if isinstance(v, dict)]
    # Sort verses in canonical order
    chosen_verses.sort(key=lambda r: (int(r.get("chapter_number") or 0), int(r.get("verse_number") or 0)))

    items = taf_row.get("content_items")
    if not isinstance(items, list):
        items = []

    by_vid = {}
    for it in items:
        if not isinstance(it, dict):
            continue
        vid = it.get("verse_id")
        if vid is None:
            continue
        by_vid[vid] = it

    field_list = _parse_field_list(fields)
    allowed_item_fields = {"verse_id", "verse_key", "text", "resource_id", "tafsir_id", "resource_name", "language_code"}

    out_items = []
    for v in chosen_verses:
        vid = v.get("id")
        it = by_vid.get(vid, {})
        obj = {
            "verse_id": vid,
            "verse_key": v.get("verse_key"),
            "text": it.get("text") if isinstance(it, dict) else None,
            "resource_id": taf_row.get("id"),
            "tafsir_id": taf_row.get("vendor_numeric_id"),
            "resource_name": taf_row.get("name"),
            "language_code": taf_row.get("language_code"),
        }
        if field_list is not None:
            obj = {k: obj.get(k) for k in field_list if k in allowed_item_fields}
            obj.setdefault("verse_id", vid)
            obj.setdefault("verse_key", v.get("verse_key"))
        out_items.append(obj)

    _log_and_count("ok", params={**params, "chosen_selector": chosen})
    return {
        "tafsir_id": taf_row.get("vendor_numeric_id"),
        "resource_id": taf_row.get("id"),
        "scope": {"type": chosen, "value": selectors.get(chosen)},
        "tafsir": out_items,
        "meta": {"total": len(out_items)},
    }

def chapter_reciters(language=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "chapter-reciters"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, params=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"qcom_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "params": params or {},
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    params = {"language": language}
    # validate language if provided
    if language is not None:
        if not isinstance(language, str) or len(language) < 2 or len(language) > 10 or re.fullmatch(r"^[a-zA-Z-]+$", language) is None:
            _log("error", params, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "language is invalid; expected 2–10 chars matching ^[a-zA-Z-]+$", field="language")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []
    reciters = [r for r in resources if isinstance(r, dict) and r.get("resource_type") == "reciter" and r.get("status") == "active"]

    def _localized_name(r):
        if language is None:
            return r.get("name")
        locs = r.get("localizations")
        if isinstance(locs, list):
            for e in locs:
                if isinstance(e, dict) and e.get("language_code") == language and isinstance(e.get("name"), str):
                    return e.get("name")
        return r.get("name")

    out = []
    for r in reciters:
        out.append({
            "id": r.get("id"),
            "reciter_id": r.get("vendor_numeric_id"),
            "name": _localized_name(r),
            "language_code": r.get("language_code"),
            "author_name": r.get("author_name"),
            "description": r.get("description"),
            "slug": r.get("slug"),
            "metadata_json": r.get("metadata_json"),
        })

    out.sort(key=lambda x: (str(x.get("name") or ""), x.get("reciter_id") if isinstance(x.get("reciter_id"), int) else 10**9))
    _log("ok", params)
    return {"reciters": out, "meta": {"total": len(out)}}

def recitation_styles(language=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
