    _log("ok", params)
    return {"recitation_styles": out, "meta": {"total": len(out)}}

def languages(language=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0095000" if __import__("os").path.isdir("./environment_mix/0095000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"qcom_req_{int(time.time()*1000)}",
                "endpoint": "languages",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "credential_used": credential_used,
                "error_code": error_code
            })
            _save("request_logs.json", logs)

    # validate language preference if provided
    if language is not None:
        if not isinstance(language, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "language must be a string", field="language")
        lang = language.strip()
        if not (2 <= len(lang) <= 10) or not re.fullmatch(r"[a-zA-Z-]+", lang):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid language", field="language")
    else:
        lang = None

    langs = _load("languages.json")
    active = [l for l in langs if isinstance(l, dict) and l.get("status") == "active"]

    # Display-language preference: no filtering, just sort by name in that preference if possible.
    # Since schema only stores name_local/name_english per language row (not translated labels), we sort by:
    # - if preference seems English-like -> name_english then name_local
    # - else -> name_local then name_english
    prefer_english = (lang is None) or (lang.lower().startswith("en"))

    def _nm(l):
        nl = l.get("name_local") if isinstance(l.get("name_local"), str) else ""
        ne = l.get("name_english") if isinstance(l.get("name_english"), str) else ""
        return (ne, nl) if prefer_english else (nl, ne)

    active.sort(key=lambda l: (str(_nm(l)[0]).lower(), str(_nm(l)[1]).lower(), str(l.get("code") or "").lower()))

    out = []
    for l in active:
        out.append({
            "id": l.get("id"),
            "code": l.get("code"),
            "name_local": l.get("name_local"),
            "name_english": l.get("name_english"),
            "rtl": l.get("rtl"),
        })

    _log("ok")
    return {"languages": out, "meta": {"count": len(out)}}
